#include <bits/stdc++.h>
using namespace std;
int main() {
    int N, K;
    cin >> N >> K;
    vector<long long> A(N);
    long long lo = 0, hi = 0;
    for (int i = 0; i < N; i++) {
        cin >> A[i];
        lo = max(lo, A[i]);
        hi += A[i];
    }
    while (lo < hi) {
        long long mid = (lo + hi) / 2;
        int cnt = 1;
        long long sum = 0;
        for (long long x : A) {
            if (sum + x > mid) {
                cnt++;
                sum = x;
            } else {
                sum += x;
            }
        }
        if (cnt <= K) hi = mid;
        else lo = mid + 1;
    }
    cout << lo << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Edge {
    int u, v;
    long long w;
    bool operator<(const Edge& other) const {
        return w < other.w;
    }
};

struct DSU {
    vector<int> fa, sz;
    DSU(int n) : fa(n+1), sz(n+1, 1) { iota(fa.begin(), fa.end(), 0); }
    int find(int x) { return fa[x] == x ? x : fa[x] = find(fa[x]); }
    bool unite(int a, int b) {
        a = find(a); b = find(b);
        if (a == b) return false;
        if (sz[a] < sz[b]) swap(a, b);
        fa[b] = a;
        sz[a] += sz[b];
        return true;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M, Q;
    cin >> N >> M >> Q;

    vector<Edge> edges(M);
    for (int i = 0; i < M; ++i) {
        cin >> edges[i].u >> edges[i].v >> edges[i].w;
    }

    // ---------- Kruskal 求 MST ----------
    sort(edges.begin(), edges.end());
    DSU dsu(N);
    vector<vector<pair<int, long long>>> tree(N + 1);

    for (auto &e : edges) {
        if (dsu.unite(e.u, e.v)) {
            tree[e.u].push_back({e.v, e.w});
            tree[e.v].push_back({e.u, e.w});
        }
    }

    // ---------- 树上倍增预处理 ----------
    const int LOG = 20; // 2^17 > 1e5，取20足够
    vector<vector<int>> up(N + 1, vector<int>(LOG));
    vector<vector<long long>> mx(N + 1, vector<long long>(LOG));
    vector<int> depth(N + 1, 0);

    function<void(int, int)> dfs = [&](int u, int p) {
        for (int j = 1; j < LOG; ++j) {
            up[u][j] = up[ up[u][j-1] ][j-1];
            mx[u][j] = max(mx[u][j-1], mx[ up[u][j-1] ][j-1]);
        }
        for (auto [v, w] : tree[u]) {
            if (v == p) continue;
            depth[v] = depth[u] + 1;
            up[v][0] = u;
            mx[v][0] = w;
            dfs(v, u);
        }
    };

    // 以1为根（图连通）
    dfs(1, 0);

    // ---------- 查询函数 ----------
    auto query = [&](int u, int v) -> long long {
        if (depth[u] < depth[v]) swap(u, v);
        long long ans = 0;
        // 提升 u 到与 v 同一深度
        int diff = depth[u] - depth[v];
        for (int j = 0; j < LOG; ++j) {
            if (diff & (1 << j)) {
                ans = max(ans, mx[u][j]);
                u = up[u][j];
            }
        }
        if (u == v) return ans;
        // 同时提升
        for (int j = LOG - 1; j >= 0; --j) {
            if (up[u][j] != up[v][j]) {
                ans = max(ans, max(mx[u][j], mx[v][j]));
                u = up[u][j];
                v = up[v][j];
            }
        }
        ans = max(ans, max(mx[u][0], mx[v][0]));
        return ans;
    };

    // ---------- 处理询问 ----------
    while (Q--) {
        int s, t;
        cin >> s >> t;
        // 图连通，所以一定有答案；若担心，可加判断
        cout << query(s, t) << '\n';
    }

    return 0;
}

