#include <bits/stdc++.h>
using namespace std;

struct Edge {
    int u, v;
    long long w;
    bool operator<(const Edge& other) const {
        return w < other.w;
    }
};

struct DSU {
    vector<int> fa, sz;
    DSU(int n) : fa(n + 1), sz(n + 1, 1) {
        for (int i = 0; i <= n; ++i) fa[i] = i;
    }
    int find(int x) {
        return fa[x] == x ? x : fa[x] = find(fa[x]);
    }
    bool unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return false;
        if (sz[a] < sz[b]) swap(a, b);
        fa[b] = a;
        sz[a] += sz[b];
        return true;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M, Q;
    cin >> N >> M >> Q;

    vector<Edge> edges(M);
    for (int i = 0; i < M; ++i) {
        cin >> edges[i].u >> edges[i].v >> edges[i].w;
    }

    sort(edges.begin(), edges.end());
    DSU dsu(N);
    vector<vector<pair<int, long long> > > tree(N + 1);

    for (int i = 0; i < M; ++i) {
        if (dsu.unite(edges[i].u, edges[i].v)) {
            tree[edges[i].u].push_back(make_pair(edges[i].v, edges[i].w));
            tree[edges[i].v].push_back(make_pair(edges[i].u, edges[i].w));
        }
    }

    const int LOG = 17;
    vector<vector<int> > up(N + 1, vector<int>(LOG, 0));
    vector<vector<long long> > mx(N + 1, vector<long long>(LOG, 0));
    vector<int> depth(N + 1, 0);

    function<void(int, int)> dfs = [&](int u, int p) {
        for (int i = 0; i < (int)tree[u].size(); ++i) {
            int v = tree[u][i].first;
            long long w = tree[u][i].second;
            if (v == p) continue;
            depth[v] = depth[u] + 1;
            up[v][0] = u;
            mx[v][0] = w;
            for (int j = 1; j < LOG; ++j) {
                up[v][j] = up[up[v][j - 1]][j - 1];
                mx[v][j] = max(mx[v][j - 1], mx[up[v][j - 1]][j - 1]);
            }
            dfs(v, u);
        }
    };
    dfs(1, 0);

    auto query = [&](int u, int v) -> long long {
        if (depth[u] < depth[v]) swap(u, v);
        long long ans = 0;
        int diff = depth[u] - depth[v];
        for (int j = 0; j < LOG; ++j) {
            if (diff & (1 << j)) {
                ans = max(ans, mx[u][j]);
                u = up[u][j];
            }
        }
        if (u == v) return ans;
        for (int j = LOG - 1; j >= 0; --j) {
            if (up[u][j] != up[v][j]) {
                ans = max(ans, max(mx[u][j], mx[v][j]));
                u = up[u][j];
                v = up[v][j];
            }
        }
        ans = max(ans, max(mx[u][0], mx[v][0]));
        return ans;
    };

    while (Q--) {
        int s, t;
        cin >> s >> t;
        cout << query(s, t) << '\n';
    }

    return 0;
}

