#include <bits/stdc++.h>
using namespace std;

const long long MOD = 1e9 + 7;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<long long> A(N);
    for (int i = 0; i < N; ++i) cin >> A[i];

    vector<int> left(N), right(N);
    stack<int> st;

    // 左边第一个小于 A[i] 的位置（严格小于，避免重复计数）
    for (int i = 0; i < N; ++i) {
        while (!st.empty() && A[st.top()] >= A[i]) st.pop();
        left[i] = st.empty() ? -1 : st.top();
        st.push(i);
    }
    while (!st.empty()) st.pop();

    // 右边第一个小于等于 A[i] 的位置（小于等于，和左边构成开区间）
    for (int i = N - 1; i >= 0; --i) {
        while (!st.empty() && A[st.top()] > A[i]) st.pop();
        right[i] = st.empty() ? N : st.top();
        st.push(i);
    }

    long long ans = 0;
    for (int i = 0; i < N; ++i) {
        // 以 A[i] 为最小值的子数组个数 = (i - left[i]) * (right[i] - i)
        long long cnt = (long long)(i - left[i]) * (right[i] - i) % MOD;
        ans = (ans + (A[i] % MOD) * cnt) % MOD;
    }

    cout << ans << '\n';
    return 0;
}

