bool check(long long d) {
    int cnt = 1;              // 第一个点必选
    long long last = X[0];
    for (int i = 1; i < N; ++i) {
        if (X[i] - last >= d) {
            cnt++;
            last = X[i];
            if (cnt >= K) return true;
        }
    }
    return cnt >= K;
}

