bool isPrime(int x) {
    if (x < 2) return false;
    for (int i = 2; i * i <= x; ++i) if (x % i == 0) return false;
    return true;
}

int divisorCount(int x) {
    int cnt = 0;
    for (int i = 1; i <= x; ++i) if (x % i == 0) cnt++;
    return cnt;
}

int digitSum(int x) {
    int s = 0;
    while (x) { s += x % 10; x /= 10; }
    return s;
}

