#include<bits/stdc++.h>
using namespace std;
typedef long long ll;
mt19937 rd(time(NULL));
const int N=1e6+10;
int n,u,v,rt,num;
ll a[N],b[N];
struct node{
    int l,r,val,sz,rk,Min,rev;
};
struct Treap{
    node T[N];
    #define l(p) T[p].l
    #define r(p) T[p].r
    #define val(p) T[p].val
    #define sz(p) T[p].sz
    #define rk(p) T[p].rk
    #define Min(p) T[p].Min
    #define rev(p) T[p].rev
    int New(int v){
        val(++num)=v;
        Min(num)=v;
        sz(num)=1;
        rk(num)=rd();
        return num;
    }
    void push_up(int p){
        sz(p)=sz(l(p))+1+sz(r(p));
        Min(p)=val(p);
        if(l(p))Min(p)=min(Min(p),Min(l(p)));
        if(r(p))Min(p)=min(Min(p),Min(r(p)));
    }
    void push_down(int p){
        if(rev(p)){
            swap(l(p),r(p));
            rev(l(p))^=1,rev(r(p))^=1;
            rev(p)=0;
        }
    }
    void split(int p,int &x,int &y,int k){
        if(!p)return void(x=y=0);
        push_down(p);
        if(sz(l(p))+1<=k){
            x=p;
            split(r(p),r(x),y,k-sz(l(p))-1);
            push_up(x);
        }
        else{
            y=p;
            split(l(p),x,l(y),k);
            push_up(y);
        }
    }
    int merge(int x,int y){
        if(!x||!y)return x|y;
        push_down(x),push_down(y);
        if(rk(x)<=rk(y)){
            r(x)=merge(r(x),y);
            push_up(x);
            return x;
        }
        else{
            l(y)=merge(x,l(y));
            push_up(y);
            return y;
        }
    }
    void reverse(int l,int r){
        split(rt,rt,u,l-1);
        split(u,u,v,r-l+1);
        rev(u)^=1;
        rt=merge(rt,merge(u,v));
    }
    int locate(int p,int v){
        push_down(p);
        // cout<<p<<' '<<v<<' '<<val(p)<<' '<<l(p)<<' '<<r(p)<<' '<<Min(l(p))<<' '<<Min(r(p))<<'\n';
        if(val(p)==v)return sz(l(p))+1;
        if(Min(l(p))==v)return locate(l(p),v);
        else return sz(l(p))+1+locate(r(p),v);
    }
}Tree;
