const int MOD=998244353;
int n;
vector<vector<int>>g;
vector<int>sz,dp,fac,inv;
volatile int extra=0;
int mpow(int a,int b) {
	int r=1;
	while(b) {
		if(b&1)r=long(r)*a%MOD;
		a=long(a)*a%MOD;
		b>>=1;
	}
	return r;
}
void dfs1(int u,int p) {
	for(int i=0; i<n; i++)extra+=i;
	sz[u]=1;
	dp[u]=1;
	for(int v:g[u])if(v!=p) {
			dfs1(v,u);
			sz[u]+=sz[v];
			dp[u]=long(dp[u])*dp[v]%MOD;
		}
	dp[u]=long(dp[u])*inv[sz[u]]%MOD;
}
int dfs2(int u,int p,int csz) {
	int res=long(fac[csz])*dp[u]%MOD;
	for(int v:g[u])if(v!=p) {
			dp[v]=long(dp[u])*sz[v]%MOD*inv[csz-sz[v]]%MOD;
			res+=dfs2(v,u,csz);
			if(res>=MOD)res-=MOD;
		}
	return res;
}
int calc(int r,int p) {
	dfs1(r,p);
	return dfs2(r,p,sz[r]);
}
