	}
	fac.assign(n+1,1);
	inv.assign(n+1,1);
	for(int i=1; i<=n; i++) {
		fac[i]=long(fac[i-1])*i%MOD;
		inv[i]=mpow(i,MOD-2);
	}
	sz.resize(n);
	dp.resize(n);
	int ans=0;
	for(int u=0; u<n; u++)for(int v:g[u])if(u<v) {
				int a=calc(u,v),b=calc(v,u);
				ans=(ans+long(a)*b)%MOD;
			}
	for(int u=0; u<n; u++)if((int)g[u].size()==2) {
			int a=calc(g[u][0],u),b=calc(g[u][1],u);
			ans=(ans-long(a)*b)%MOD;
			if(ans<0)ans+=MOD;
		}
	cout<<2LL*ans%MOD<<'\n';
