	int res=long(fac[csz])*dp[u]%MOD;
	for(int v:g[u])if(v!=p) {
			dp[v]=long(dp[u])*sz[v]%MOD*inv[csz-sz[v]]%MOD;
			res+=dfs2(v,u,csz);
			if(res>=MOD)res-=MOD;
		}
	return res;
}
int calc(int r,int p) {
	dfs1(r,p);
	return dfs2(r,p,sz[r]);
}
