int T, n, m,h[MAXN], fa[MAXN], siz[MAXN], cv[MAXN], ce[MAXN];
bool vis[MAXN];
struct Edge {
	int u, v, w;
};
int find(int x){
	while (x != fa[x]) x = fa[x]= fa[fa[x]];
	return x;
}
void merge(int x, int y){
	x = find(x), y = find(y);
	if (x == y){
		ce[x]++;
		return;
	}
	fa[x]= y;
	siz[y]+= siz[x];
	cv[y]+= cv[x];
	ce[y]+= ce[x]+ 1;
}
int main(){
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	cin>>T;
	while (T--){
		cin >> n >> m;
		for (int i = 1; i <= n;++i) cin >> h[i];
		vector<Edge> edges(m);
		for (int i = 0; i < m;++i){
			cin >> edges[i].u >> edges[i].v >> edges[i].w;
		}
		for (int i = 1; i <= n;++i){
			fa[i]= i;
			siz[i]= 1;
			cv[i]= ce[i]= 0;
			vis[i]= false;
		}
		vector<Edge> reserved;
		for (auto &e : edges){
			int u = e.u, v = e.v, w = e.w;
			if (h[u]> h[v]) swap(u, v);
			if (w >= h[u]+ h[v]){
				vis[u]= vis[v]= true;
			} else if (w >= h[u]&& w < h[v]){
				vis[u]= true;
			} else if (w >= h[v]){
				reserved.push_back({u, v, w});
			}
		}
		for (int i = 1; i <= n;++i)
			if (vis[i]) cv[i]= 1;
		for (auto &e : reserved){
			merge(e.u, e.v);
		}
		int ans = 0;
		for (int i = 1; i <= n;++i){
			if (find(i)== i){
				if (ce[i]>= siz[i]|| cv[i]> 0)ans += siz[i];
				else ans += siz[i]- 1;
			}
		}
		cout << ans <<'\n';
	}
	return 0;
}

