#include<bits/stdc++.h>
using namespace std;
#define int long long
const int MAXN=500005;
int n,q;
struct Node {
	int a,b,c,d;
} now[MAXN],tag[MAXN*4],d[MAXN*4];
bool ok(const Node&x) {
	return x.a<=x.c&&x.b<=x.d;
}
Node p(Node x,Node y) {
	if(!ok(x))return x;
	if(!ok(y))return y;
	Node res;
	res.a=max(x.a,y.a);
	res.b=max(x.b,y.b);
	res.c=min(x.c,y.c);
	res.d=min(x.d,y.d);
	if(!ok(res)) {
		res.a=1;
		res.c=0;
		res.b=1;
		res.d=0;
	}
	return res;
}
void pushup(int u) {
	d[u]=p(d[u*2],d[u*2+1]);
}
void apply(int u,int x,int y) {
	d[u].a+=x;
	d[u].c+=x;
	d[u].b+=y;
	d[u].d+=y;
	tag[u].a+=x;
	tag[u].b+=y;
}
void pushdown(int u) {
	if(tag[u].a==0&&tag[u].b==0)return;
	apply(u*2,tag[u].a,tag[u].b);
	apply(u*2+1,tag[u].a,tag[u].b);
	tag[u].a=tag[u].b=0;
}
void build(int u,int l,int r) {
	if(l==r) {
		d[u]=now[l];
		return;
	}
	int m=l+((r-l)>>1);
	build(u*2,l,m);
	build(u*2+1,m+1,r);
	pushup(u);
}
void insert(int u,int l,int r,int s,int t,int a,int b) {
	if(s<=l&&r<=t) {
		apply(u,a,b);
		return;
	}
	pushdown(u);
	int m=l+((r-l)>>1);
	if(s<=m)insert(u*2,l,m,s,t,a,b);
	if(t>m)insert(u*2+1,m+1,r,s,t,a,b);
	pushup(u);
}
Node query(int u,int l,int r,int s,int t) {
	if(s<=l&&r<=t)return d[u];
	pushdown(u);
	int m=l+((r-l)>>1);
	if(t<=m)return query(u*2,l,m,s,t);
	if(s>m)return query(u*2+1,m+1,r,s,t);
	return p(query(u*2,l,m,s,t),query(u*2+1,m+1,r,s,t));
}
main() {
//	freopen("square6.in","r",stdin);
//	freopen("test.out","w",stdout);
	 
	cin>>n>>q;
	for(int i=1; i<=n; i++)cin>>now[i].a>>now[i].b>>now[i].c>>now[i].d;
	build(1,1,n);
	for(int i=1; i<=q; i++) {
		char c;
		cin>>c;
		if(c=='Q') {
			int l,r;
			cin>>l>>r;
			Node k=query(1,1,n,l,r);
			cout<<(ok(k)?"Yes":"No")<<'\n';
		} else {
			int l,r,x,y;
			cin>>l>>r>>x>>y;
			insert(1,1,n,l,r,x,y);
		}
	}
	return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int INF=1000000003;
vector<int > mn,mx,pos;
int n,q,sz;
void build() {
	sz=1;
	while(sz<n+1)sz<<=1;
	mn.assign(2*sz,INF);
	mx.assign(2*sz,-1);
	for(int v=0; v<=n; ++v)mn[sz+v]=mx[sz+v]=pos[v];
	for(int i=sz-1; i>=1; --i) {
		mn[i]=min(mn[i<<1],mn[i<<1|1]);
		mx[i]=max(mx[i<<1],mx[i<<1|1]);
	}
}
int firstBelow(int l) {
	if(mn[1]>=l)return -1;
	int i=1;
	while(i<sz)i=(mn[i<<1]<l)?(i<<1):(i<<1|1);
	return i-sz;
}
int firstAbove(int r) {
	if(mx[1]<=r)return -1;
	int i=1;
	while(i<sz)i=(mx[i<<1]>r)?(i<<1):(i<<1|1);
	return i-sz;
}
int main() {
	int q;
	scanf("%d%d",&n,&q);
	pos.assign(n+1,-1);
	for(int i=1;i<=n;++i){
		int x;
		scanf("%d",&x);
		if(0<=x&&x<=n)pos[x]=i;
	}
	build();
	while(q--){
		int l,r;
		scanf("%d%d",&l,&r);
		int a=firstBelow(l),b=firstAbove(r);
		int ans=(a<0)?b:(b<0?a:min(a,b));
		printf("%d\n",ans);
	}
	return 0;
}

