inline void read(int &x){
    char ch=getchar();
    x=0;
    while(!isdigit(ch)) ch=getchar();
    while(isdigit(ch)) x=x*10+ch-48,ch=getchar();
}
const int N=510;
const int Q=10010;
const long long INF=4e18;
int n,m,q,a[N];
long long d[N][N],ans[Q];
struct Query{
    int s,t;
}que[Q];
int main(){
    read(n),read(m);
    for(int i=1;i<=n;++i) read(a[i]);
    for(int i=1;i<=n;++i)
        for(int j=1;j<=n;++j)
            d[i][j]=(i==j?0:INF);
    for(int i=1,u,v,w;i<=m;++i){
        read(u),read(v),read(w);
        d[u][v]=min(d[u][v],(long long)w);
    }
    read(q);
    for(int i=1;i<=q;++i){
        read(que[i].s),read(que[i].t);
        ans[i]=INF;
    }
    vector<int> ord(n);
    iota(ord.begin(),ord.end(),1);
    sort(ord.begin(),ord.end(),[](int x,int y){
        return a[x]<a[y];
    });
    for(int p=0;p<n;){
        int r=p;
        while(r<n&&a[ord[r]]==a[ord[p]]){
            int x=ord[r];
            for(int i=1;i<=n;++i){
                if(d[i][x]==INF) continue;
                for(int j=1;j<=n;++j){
                    if(d[x][j]==INF) continue;
                    d[i][j]=min(d[i][j],d[i][x]+d[x][j]);
                }
            }

            ++r;
        }
        int A=a[ord[p]];
        for(int i=1;i<=q;++i){
            int s=que[i].s;
            int t=que[i].t;
            if(a[s]>A||a[t]>A||d[s][t]==INF) continue;

            ans[i]=min(ans[i],(long long)A*d[s][t]);
        }

        p=r;
    }
    for(int i=1;i<=q;++i){
        if(ans[i]==INF) puts("-1");
        else printf("%lld\n",ans[i]);
    }

    return 0;
}

